param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'nullable-int32-type-metadata-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$rows=[Collections.Generic.List[object]]::new()
function Names($types){return (($types|ForEach-Object {if($null -eq $_.FullName){$_.Name}else{$_.FullName}})-join ';')}
foreach($shape in $plan.shapes){$type=switch($shape){'D'{[object].Assembly.GetType('System.Nullable`1')};'C'{([object].Assembly.GetType('System.Nullable`1')).MakeGenericType([type[]]@([int]))};'P'{([object].Assembly.GetType('System.Nullable`1')).GetGenericArguments()[0]}};foreach($field in $plan.fields){$value=switch($field){'BaseType'{$type.BaseType.FullName};'DeclaringType'{if($null -ne $type.DeclaringType){$type.DeclaringType.FullName}};'GenericArguments'{Names ($type.GetGenericArguments())};'GenericTypeArguments'{Names $type.GenericTypeArguments};'ArgumentsDefensiveCopy'{$a=$type.GetGenericArguments();$result=$true;if($a.Length -gt 0){$saved=$a[0];$a[0]=$null;$result=[object]::ReferenceEquals($saved,$type.GetGenericArguments()[0])};$result};'GenericTypeArgumentsDefensiveCopy'{$a=$type.GenericTypeArguments;$result=$true;if($a.Length -gt 0){$saved=$a[0];$a[0]=$null;$result=[object]::ReferenceEquals($saved,$type.GenericTypeArguments[0])};$result};default{$type.$field}};if($value -is [bool]){$value=$(if($value -is [bool]){$value.ToString().ToLowerInvariant()}else{$value.ToString()})};$rows.Add([ordered]@{shape=$shape;field=$field;value=$value})};if($shape -eq 'P'){foreach($field in @('GenericParameterAttributes','GenericParameterPosition','Constraints','ConstraintsDefensiveCopy')){$value=switch($field){'GenericParameterAttributes'{[int]$type.GenericParameterAttributes};'GenericParameterPosition'{$type.GenericParameterPosition};'Constraints'{Names ($type.GetGenericParameterConstraints())};'ConstraintsDefensiveCopy'{$a=$type.GetGenericParameterConstraints();$saved=$a[0];$a[0]=$null;[object]::ReferenceEquals($saved,$type.GetGenericParameterConstraints()[0])}};$rows.Add([ordered]@{shape=$shape;field=$field;value=$(if($value -is [bool]){$value.ToString().ToLowerInvariant()}else{$value.ToString()})})}}else{$rows.Add([ordered]@{shape=$shape;field='GenericDefinition';value=$type.GetGenericTypeDefinition().FullName})}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS Nullable metadata: $($rows.Count) fields"
